// ── Shapes ──────────────────────────────────────────────────────────────────────

/**
 * chat.history params. dist/sessions-rlbLHLas.mjs:1560 `ChatHistoryParamsSchema` is a
 * closedObject (additionalProperties: false, dist/closed-object-DGvQfpTV.mjs:5), so an
 * unknown key is an INVALID_REQUEST. 2026.6.5 accepts ONLY sessionKey/agentId/limit/maxChars
 * (dist/schema-KBhSSPA3.js:2696) — `offset` there is rejected.
 */
export interface ChatHistoryParams {
  sessionKey: string
  agentId?: string
  cursor?: string
  limit?: number          // 1..1000, default 200; counts VISIBLE (projected) messages
  maxBytes?: number       // >= 1024; capped at 6 MiB
  offset?: number         // >= 0; raw transcript records back from the newest
  pendingBefore?: number
  inputRunIds?: string[]
  messageId?: string      // can't combine with offset (handler :604) or cursor (:608)
  sessionId?: string      // requires messageId (:612)
  maxChars?: number       // 1..500000, default 8000
}

/**
 * `__openclaw` transcript metadata on each history row.
 * dist/session-transcript-readers-BZjuw2hz.mjs:2170 projectTranscriptEntryMessage (id, seq,
 * recordTimestampMs, transcriptPosition), :1782 (truncated + reason "display-cap"),
 * dist/chat-history-handler-DpOELHcj.mjs:74 (oversized placeholder: truncated + reason "oversized").
 * The id is ONLY here — messages have no top-level `id` (dist/session-history-tail--_AS1rfq.mjs:48).
 */
export interface OpenClawMeta {
  id?: string
  seq?: number
  recordTimestampMs?: number
  idempotencyKey?: string
  transcriptPosition?: {
    source: string
    rawSeq: number
    activity?: { afterRawSeq: number | null; scopeId: string; startOrder: number }
  }
  kind?: 'compaction' | 'reset'
  runId?: string
  turnBoundary?: boolean
  truncated?: boolean
  reason?: string          // 'display-cap' | 'oversized' | ...
  tokensBefore?: number
  tokensAfter?: number
  senderIdentity?: unknown
}

/** Content blocks as projected. Tool spellings: dist/chat-display-projection.canvas-hWMu3XQA.mjs:139. */
export type HistoryBlock =
  | { type: 'text'; text: string; textSignature?: string }
  | { type: 'thinking'; thinking: string }   // thinkingSignature is deleted (session-transcript-readers:1494)
  | { type: 'toolCall'; id: string; name: string; arguments: unknown; runId?: string; parentToolCallId?: string; timestamp?: number }
  | { type: 'tool_use'; id: string; name: string; input: unknown }
  | { type: 'toolResult'; role?: 'toolResult'; toolCallId: string; toolName: string; content: HistoryBlock[]; isError: boolean; [k: string]: unknown }
  // media: data/blob/path stripped, omitted:true, bytes estimated (session-transcript-readers:1384)
  | { type: 'image' | 'audio' | 'video'; mimeType?: string; url?: string; omitted?: boolean; bytes?: number }
  | { type: 'attachment'; attachment: { name?: string; mimeType?: string; url?: string; sizeBytes?: number } }
  | { type: 'canvas'; preview: unknown; rawText: string | null }

/**
 * One chat.history row. Role set: user | assistant | toolResult | system (compaction/reset
 * marker, session-transcript-readers:2205) | custom (display:true custom_message, incl. nested
 * tool activity, :2185). Assistant `usage`/`cost` sanitized at :1611; stripped from non-assistant rows (:1690).
 */
export interface HistoryMessage {
  role: 'user' | 'assistant' | 'toolResult' | 'system' | 'custom'
  content: string | HistoryBlock[]
  timestamp?: number
  // assistant
  api?: string
  provider?: string
  model?: string
  usage?: {
    input?: number; output?: number; cacheRead?: number; cacheWrite?: number; totalTokens?: number
    cost?: { input?: number; output?: number; cacheRead?: number; cacheWrite?: number; total?: number }
  }
  stopReason?: string
  errorMessage?: string
  phase?: string
  // toolResult
  toolCallId?: string
  toolName?: string
  isError?: boolean
  details?: Record<string, unknown>   // allow-list only: diff/changed/created/browserTab/approvalReviews/mcpAppPreview (chat-display-projection.canvas:356)
  // user (channel): session-transcript-readers:61 extractMessageSenderLabel → :100 top-level senderLabel
  senderLabel?: string
  // custom
  customType?: string
  display?: boolean
  excludeFromContext?: boolean
  runId?: string
  __openclaw?: OpenClawMeta
}

/**
 * Subset of `sessionInfo` (buildGatewaySessionRow, dist/session-utils-list-RGkE30m3.mjs:1079,
 * fields :1266-1382) plus handler additions dist/chat-history-handler-DpOELHcj.mjs:837-847.
 */
export interface ChatHistorySessionInfo {
  key: string
  kind?: string
  sessionId?: string
  displayName?: string
  label?: string
  derivedTitle?: string
  updatedAt?: number
  modelProvider?: string
  model?: string
  thinkingLevel?: string
  verboseLevel?: string
  totalTokens?: number
  contextTokens?: number
  hasActiveRun: boolean
  activeRunIds?: string[]
  status?: string          // 'running' when hasActiveRun (:839)
  activeLeafEntryId?: string | null
  [k: string]: unknown
}

/** dist/sessions-rlbLHLas.mjs:1595 ChatPendingInputsPageSchema. */
export interface ChatPendingInputsPage {
  items: { id: string; runId?: string; message: unknown; acceptedAt: number; state: 'queued' | 'cancelled' | 'interrupted' }[]
  total: number
  nextBefore?: number
}

/**
 * Tail/offset response. dist/chat-history-handler-DpOELHcj.mjs:948-966. `offset` only when the
 * request sent one (:958 responseOffset); `nextOffset` only when hasMore; `hasMore` and
 * `totalMessages` only when pagination exists (always on a 9.4 tail/offset page, never on 6.5).
 * `totalMessages` counts RAW transcript records, not the visible rows returned.
 */
export interface ChatHistoryResponse {
  sessionKey: string
  sessionId?: string
  messages: HistoryMessage[]
  pendingInputs?: ChatPendingInputsPage
  deltaCursor?: string
  offset?: number
  nextOffset?: number
  hasMore?: boolean
  totalMessages?: number
  completeSnapshot?: boolean
  defaults?: Record<string, unknown>
  sessionInfo: ChatHistorySessionInfo
  thinkingLevel?: string
  fastMode?: boolean | 'auto'
  toolOverrides?: unknown
  verboseLevel?: string
  inFlightRun?: unknown
}

/** dist/error-codes-C3Z5XSDw.mjs:65 errorShape → `{ code, message, ...opts }`. */
export interface GatewayErrorShape {
  code: 'INVALID_REQUEST' | 'FORBIDDEN' | 'UNAVAILABLE' | 'NOT_PAIRED' | string
  message: string
  details?: Record<string, unknown>
  retryable?: boolean
  retryAfterMs?: number
}

/** dist/message-handler-BBAGn2rf.mjs:279 response frame. */
export interface GatewayResponseFrame<T> {
  type: 'res'
  id: string
  ok: boolean
  payload?: T
  error?: GatewayErrorShape
}

/** dist/sessions-rlbLHLas.mjs:1701 params, :1709-1717 result. */
export interface ChatMessageGetParams { sessionKey: string; agentId?: string; messageId: string; maxChars?: number }
export interface ChatMessageGetResult { ok: boolean; message?: HistoryMessage; unavailableReason?: 'not_found' | 'oversized' | 'not_visible' }

/** session.message event payload. dist/session-transcript-readers-BZjuw2hz.mjs:2131 projectSessionMessagePayload. */
export interface SessionMessageEventPayload {
  sessionKey: string
  senderIsOwner?: boolean
  agentId?: string
  message: HistoryMessage
  messageId?: string
  messageSeq?: number
  runId?: string
  [k: string]: unknown   // + buildGatewaySessionSnapshot fields
}

/** The export envelope PRD 05 §5.4 specifies for JSON (app-side, not a gateway shape). */
export interface ChatExportJsonEnvelope {
  exportedAt: string
  sessionKey: string
  title: string
  agentId: string
  totalMessages: number
  messages: HistoryMessage[]
}

